# Filter driver standings to find drivers who won (position 1) and had more than 20 points.
winning_drivers_info = formula_1.driverstanding.WHERE(
    (position == 1) & (points > 20)
).CALCULATE(
    # Access the driver's first name from the joined 'driver' collection
    driver_first_name=driver.forename
)

