    name="drivers", by=driver_first_name
).CALCULATE(
    first_name=driver_first_name
)

races_by_time_condition = formula_1.race.CALCULATE(
    # Combine date and time strings into a full datetime string, then parse it
    # This ensures proper datetime object for hour extraction.
    full_race_datetime=DATETIME(JOIN_STRINGS(' ', date, time))
).WHERE(
    # Filter based on the hour component of the parsed datetime object
    (HOUR(full_race_datetime) > 12) | (HOUR(full_race_datetime) < 9)
).CALCULATE(
    race_name=name
)

